test('invoiceTotals calculates discount', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 5 * 9500 = 47500
  // discount = 47500 * 10 / 100 = 4750
  // total = 47500 - 4750 = 42750
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.total, 42750);
});

test('invoiceTotals with multiple lines applies discount to each', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 9500, discountPercent: 10 },
      { qty: 1, unitPrice: 120000, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 3 * 9500 = 28500, discount = 2850
  // line 2: 1 * 120000 = 120000, discount = 6000
  // subtotal = 148500
  // discount = 8850
  // total = 139650
  assert.equal(totals.subtotal, 148500);
  assert.equal(totals.discount, 8850);
  assert.equal(totals.total, 139650);
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 150 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100
  // discount = 150 (clamped to 100 by the calculation)
  // But actually discount would be 100 * 150 / 100 = 150
  // total = 100 - 150 = -50 → clamped to 0
  assert.equal(totals.total, 0);
});

