  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 0 }), 0);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21 },
      { qty: 1, unitPrice: 10000, vatRate: 9 },
      { qty: 1, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 30000
  // line 1 vat = 10000 * 21 / 100 = 2100
  // line 2 vat = 10000 * 9 / 100 = 900
  // line 3 vat = 0
  // vat = 3000
  // total = 30000 + 3000 = 33000
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, 3000);
  assert.equal(totals.total, 33000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { qty: 1, unitPrice: 10000, vatRate: 9, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 10000, discount 1000, amount 9000, vat = 1890
  // line 2: 10000, discount 500, amount 9500, vat = 855
  // subtotal = 20000, discount = 1500, vat = 2745
  // total = 20000 - 1500 + 2745 = 21245
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 2745);
  assert.equal(totals.total, 21245);
});

